reps = {}
donation_counts = {}
recent_donations = {}  # list of recent actions (True for donate) for each donor

def evaluate(current_reputation, observation, my_history, round_num):
    donor = observation["donor"]
    recipient = observation["recipient"]
    action = observation["action"]
    rec_rep = reps.get(recipient, 0.01)

    # Update donation count and recent list for donor
    if action == "donate":
        donation_counts[donor] = donation_counts.get(donor, 0) + 1

    # Maintain a sliding window of last 10 actions for donor (True=donated)
    if donor not in recent_donations:
        recent_donations[donor] = []
    recent_donations[donor].append(action == "donate")
    if len(recent_donations[donor]) > 10:
        recent_donations[donor].pop(0)

    # Calculate recent donation rate (last 10 rounds)
    recent_rate = sum(recent_donations[donor]) / max(len(recent_donations[donor]), 1)

    # Base delta using modified scoring (more weight on recent reputation)
    if action == "donate":
        if rec_rep > 0:
            delta = 0.4
        else:
            delta = -0.2
    else:  # not donate
        if rec_rep > 0:
            delta = -0.4
        else:
            delta = 0.2

    # Adjust delta based on recent donation consistency
    if recent_rate > 0.7:
        delta += 0.15 * (1 if action == "donate" else -1)
    elif recent_rate < 0.3:
        delta -= 0.1 * (1 if action == "donate" else -1)

    # Exponentially weighted update (recency emphasis)
    decay = 0.3  # higher = more weight on new observations
    new_rep = (1 - decay) * current_reputation + decay * delta
    new_rep = max(-1.0, min(1.0, new_rep))

    reps[donor] = new_rep
    return new_rep


def decide(recipient_reputation, round_num, my_history):
    # Compute own donation streak from recent history
    streak = 0
    for entry in reversed(my_history):
        if entry.get('action') == 'donate':
            streak += 1
        else:
            break

    # Base threshold shifts with round and streak
    if round_num < 30:
        base = -0.3
    elif round_num < 80:
        base = 0.0
    else:
        base = 0.2

    # Lower threshold if I've been donating consistently (generous streak)
    if streak >= 3:
        base -= 0.15
    elif streak == 0:
        base += 0.1

